(() => {
  // 自动定位主酒馆窗口（兼容 iframe 沙箱）
  let W = window;
  try { while (!W.document.getElementById('chat') && W !== W.parent) W = W.parent; } catch (e) {}
  const D = W.document, chat = D.getElementById('chat');
  if (!chat) return console.warn('[批注] 找不到 #chat');

  W.__anno?.();
  D.getElementById('anno-style')?.remove();
  const css = D.createElement('style');
  css.id = 'anno-style';
  css.textContent = `
    .anno{cursor:pointer;border-bottom:1.5px dashed #c9962f;}
    .anno-高燃{border-bottom-color:#d9534f;} .anno-转折{border-bottom-color:#7e6bd6;}
    .anno-pop{position:fixed;z-index:99999;max-width:228px;padding:9px 12px 8px;border-radius:15px;
      font-size:12px;line-height:1.6;letter-spacing:.01em;
      background:rgba(255,255,255,.58);
      -webkit-backdrop-filter:blur(24px) saturate(185%);backdrop-filter:blur(24px) saturate(185%);
      border:1px solid rgba(255,255,255,.55);
      box-shadow:0 10px 34px rgba(0,0,0,.13),inset 0 1px 0 rgba(255,255,255,.45);
      color:#1c1c1e;opacity:0;transform:translateY(5px) scale(.98);
      transition:opacity .2s cubic-bezier(.2,.7,.2,1),transform .2s cubic-bezier(.2,.7,.2,1);}
    .anno-pop.show{opacity:1;transform:none;}
    .anno-pop .row{margin:3px 0;}
    .anno-pop b{color:#b8860b;font-weight:600;}
    .anno-mono{font-style:italic;padding-left:9px;border-left:2px solid #c9962f;opacity:.9;}
    .anno-foot{margin-top:7px;padding-top:6px;border-top:1px solid rgba(0,0,0,.08);
      font-size:10.5px;color:rgba(0,0,0,.38);text-align:center;letter-spacing:.04em;}
    @media (prefers-color-scheme:dark){
      .anno-pop{background:rgba(28,28,30,.52);border-color:rgba(255,255,255,.13);color:#f2f2f2;
        box-shadow:0 10px 34px rgba(0,0,0,.5),inset 0 1px 0 rgba(255,255,255,.08);}
      .anno-pop b{color:#e3b341;}
      .anno-mono{border-left-color:#e3b341;}
      .anno-foot{color:rgba(255,255,255,.36);border-top-color:rgba(255,255,255,.1);}
    }`;
  D.head.appendChild(css);

  const RE = /\[\[(金句|高燃|转折)\]\]([\s\S]*?)\[\[网友\]\]([\s\S]*?)\[\[心声\]\]([\s\S]*?)\[\[\/\]\]/g;
  const ea = s => s.replace(/"/g, '&quot;');
  const scan = () => D.querySelectorAll('#chat .mes_text').forEach(el => {
    if (!el.innerHTML.includes('[[')) return;
    el.innerHTML = el.innerHTML.replace(RE, (_, t, txt, c, m) =>
      `<span class="anno anno-${t}" data-c="${ea(c.trim())}" data-m="${ea(m.trim())}">${txt}</span>`);
  });
  scan();
  const obs = new MutationObserver(() => scan());
  obs.observe(chat, { childList: true, subtree: true });

  const esc = s => s.replace(/[&<>]/g, c => ({ '&':'&amp;','<':'&lt;','>':'&gt;' }[c]));
  let pop = null, cur = null;
  const closePop = () => { pop?.remove(); pop = null; cur = null; };
  const show = (span, view) => {
    closePop();
    pop = D.createElement('div'); pop.className = 'anno-pop';
    if (view === 'c') {
      pop.innerHTML = (span.dataset.c || '').split('｜').map(s =>
        `<div class="row"><b>${esc(s.split(/：|:/)[0])}</b>：${esc(s.split(/：|:/).slice(1).join(''))}</div>`).join('')
        + '<div class="anno-foot">再点一下 · 看心声 ↺</div>';
    } else {
      pop.innerHTML = `<div class="anno-mono">${esc(span.dataset.m || '')}</div>`
        + '<div class="anno-foot">再点一下 · 收起</div>';
    }
    D.body.appendChild(pop);
    const r = span.getBoundingClientRect();
    pop.style.left = Math.max(8, Math.min(r.left, W.innerWidth - pop.offsetWidth - 8)) + 'px';
    pop.style.top = (r.bottom + 8) + 'px';
    requestAnimationFrame(() => pop.classList.add('show'));
    cur = { span, view };
  };
  const onClick = (e) => {
    const span = e.target.closest('.anno');
    if (span) {
      e.stopPropagation();
      if (cur?.span !== span) show(span, 'c');
      else if (cur.view === 'c') show(span, 'm');
      else closePop();
    } else if (e.target.closest('.anno-foot') && cur) {
      cur.view === 'c' ? show(cur.span, 'm') : closePop();
    } else if (!e.target.closest('.anno-pop')) closePop();
  };
  D.addEventListener('click', onClick, true);

  W.__anno = () => { obs.disconnect(); D.removeEventListener('click', onClick, true); closePop(); css.remove(); };
})();
